      # run your test suite against the generated output
      ${gen}/bin/run-tests
      touch $out
    '';
  };
}
```

After this, the flake exposes `checks.package` (the generated package) plus `checks.unit` (your test), so a CI job running `nix flake check` (or `nix flake check --no-build` to just evaluate) covers both.

